CONANCE=CON+[['拉丁 consonantia → 古法语 consonance','和谐、相合'],['英语 consonance','和谐；辅音的呼应']]
ASS=V+[['拉丁 ad- 向、相应 + sonare → assonare','呼应、声音相合；d 在 s 前同化']]
DIS=V+[['拉丁 dis- 分开、不合 + sonare → dissonare','声音不协调']]
SONOR=V+[['拉丁 sonor 声响 → sonorus','响亮的、回荡的']]
